import {getSharedGameConsoleHtml} from './gomoku-console.mjs';
// Browser-only source bundles embedded at build time. Contract tests enforce source parity.
const trainingRules="// Server-authoritative, deterministic two-player board engines. No browser-submitted board state.\nconst inBounds=(r,c,n)=>r>=0&&c>=0&&r<n&&c<n;\nconst index=(r,c,n)=>r*n+c;\nconst coords=(p,n)=>[Math.floor(p/n),p%n];\nconst side=x=>x===1||x===3?1:x===2||x===4?2:0;\nconst dirs=[[-1,-1],[-1,1],[1,-1],[1,1]];\n\nexport function initialGame(game){\n if(game==='gomoku')return {board:Array(225).fill(0),turn:1,winner:0,moves:0};\n if(game==='warcaby'){\n  const board=Array(64).fill(0);\n  for(let r=0;r<8;r++)for(let c=0;c<8;c++){\n   if((r+c)%2!==1)continue;\n   if(r<3)board[index(r,c,8)]=1;\n   if(r>4)board[index(r,c,8)]=2;\n  }\n  return {board,turn:1,winner:0,moves:0,forced:null,quiet:0};\n }\n throw Error('UNKNOWN_GAME');\n}\nexport function legalCaptures(board,turn,from){\n const [r,c]=coords(from,8),piece=board[from];\n if(side(piece)!==turn)return [];\n const results=[];\n for(const [dr,dc] of dirs){\n  if(piece<=2&&dr!==(turn===1?1:-1))continue;\n  if(piece<=2){\n   const mr=r+dr,mc=c+dc,tr=r+2*dr,tc=c+2*dc;\n   if(!inBounds(mr,mc,8)||!inBounds(tr,tc,8))continue;\n   const mid=index(mr,mc,8),to=index(tr,tc,8);\n   if(side(board[mid])===3-turn&&board[to]===0)results.push({from,to,taken:mid});\n   continue;\n  }\n  let rr=r+dr,cc=c+dc,taken=null;\n  while(inBounds(rr,cc,8)){\n   const at=index(rr,cc,8),occupant=board[at];\n   if(!occupant){\n    if(taken!==null)results.push({from,to:at,taken});\n   }else if(taken===null&&side(occupant)===3-turn){\n    taken=at;\n   }else break;\n   rr+=dr;cc+=dc;\n  }\n }\n return results;\n}\nfunction hasCapture(board,turn){\n return board.some((piece,i)=>side(piece)===turn&&legalCaptures(board,turn,i).length>0);\n}\nfunction canMove(board,turn){\n if(hasCapture(board,turn))return true;\n for(let i=0;i<64;i++)if(side(board[i])===turn){\n  const [r,c]=coords(i,8),piece=board[i];\n  for(const [dr,dc] of dirs){\n   if(piece<=2&&dr!==(turn===1?1:-1))continue;\n   const nr=r+dr,nc=c+dc;\n   if(inBounds(nr,nc,8)&&board[index(nr,nc,8)]===0)return true;\n  }\n }\n return false;\n}\nfunction playGomoku(state,move){\n const to=move?.to;\n if(!Number.isInteger(to)||to<0||to>=225||state.board[to]!==0)\n  return {error:'NIEDOZWOLONY_RUCH'};\n const board=state.board.slice();board[to]=state.turn;\n const [r,c]=coords(to,15);\n let won=false;\n for(const [dr,dc] of [[1,0],[0,1],[1,1],[1,-1]]){\n  let total=1;\n  for(const direction of [-1,1]){\n   for(let k=1;k<=4;k++){\n    const rr=r+dr*k*direction,cc=c+dc*k*direction;\n    if(!inBounds(rr,cc,15)||board[index(rr,cc,15)]!==state.turn)break;\n    total++;\n   }\n  }\n  if(total>=5){won=true;break;}\n }\n const moves=state.moves+1;\n const winner=won?state.turn:moves===225?3:0;\n return {state:{board,turn:winner?state.turn:3-state.turn,winner,moves}};\n}\nfunction playWarcaby(state,move){\n const from=move?.from,to=move?.to,board=state.board;\n const forced=state.forced??null; // Existing saved games may predate the forced field.\n if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||from>=64||to<0||to>=64||\n  board[to]!==0||side(board[from])!==state.turn||(forced!==null&&forced!==from))\n  return {error:'NIEDOZWOLONY_RUCH'};\n const [r,c]=coords(from,8),[nr,nc]=coords(to,8),dr=nr-r,dc=nc-c;\n if(!dr||Math.abs(dr)!==Math.abs(dc))return {error:'NIEDOZWOLONY_RUCH'};\n const piece=board[from];\n const capture=legalCaptures(board,state.turn,from).find(x=>x.to===to);\n const mustCapture=forced!==null||hasCapture(board,state.turn);\n if(!capture){\n  if(mustCapture)return {error:'BICIE_OBOWIAZKOWE'};\n  if(piece<=2){\n   if(Math.abs(dr)!==1||dr!==(state.turn===1?1:-1))return {error:'NIEDOZWOLONY_RUCH'};\n  }else{\n   const stepR=Math.sign(dr),stepC=Math.sign(dc);\n   for(let k=1;k<Math.abs(dr);k++){\n    if(board[index(r+k*stepR,c+k*stepC,8)]!==0)return {error:'NIEDOZWOLONY_RUCH'};\n   }\n  }\n }\n const next=board.slice();next[from]=0;next[to]=piece;\n if(capture)next[capture.taken]=0;\n const promote=(piece===1&&nr===7)||(piece===2&&nr===0);\n if(promote)next[to]=state.turn===1?3:4;\n // A man crowned during a capture continues immediately as a flying king.\n const continued=!!capture&&legalCaptures(next,state.turn,to).length>0;\n const turn=continued?state.turn:3-state.turn;\n const quiet=capture||piece<=2?0:(state.quiet??0)+1;\n const moves=state.moves+1;\n const winner=quiet>=80?3:!continued&&!canMove(next,turn)?state.turn:0;\n return {state:{...state,board:next,turn:winner?state.turn:turn,winner,moves,forced:continued?to:null,quiet}};\n}\nexport function playMove(game,state,player,move){\n const expected=game==='gomoku'?225:game==='warcaby'?64:0;\n if(!expected||!state||!Array.isArray(state.board)||state.board.length!==expected||\n  ![1,2].includes(state.turn)||![0,1,2,3].includes(state.winner)||\n  !Number.isInteger(state.moves)||state.moves<0)return {error:'NIEPRAWIDLOWY_STAN'};\n if(state.winner!==0)return {error:'PARTIA_ZAKONCZONA'};\n if(player!==state.turn)return {error:'NIE_TWOJA_TURA'};\n return game==='gomoku'?playGomoku(state,move):playWarcaby(state,move);\n}\n";
const trainingBot="// Lightweight local Warcaby opponent. Uses exactly the same rules module as online games.\n// No account APIs or server-side bot workers are required.\nimport {initialGame, playMove, legalCaptures} from '/konto/warcaby/rules.mjs';\nexport {initialGame, playMove, legalCaptures};\n\nconst side=piece=>(piece===1||piece===3)?1:(piece===2||piece===4)?2:0;\nconst diagonals=[[-1,-1],[-1,1],[1,-1],[1,1]];\nconst inside=(r,c)=>r>=0&&r<8&&c>=0&&c<8;\nconst countPieces=(board,player)=>board.filter(p=>side(p)===player).length;\n\nexport function legalMoves(state){\n if(!state||state.winner||!Array.isArray(state.board)||state.board.length!==64)return [];\n const board=state.board,turn=state.turn,forced=state.forced??null;\n const starts=forced!==null?[forced]:board.map((p,i)=>side(p)===turn?i:-1).filter(i=>i>=0);\n const captures=starts.flatMap(from=>legalCaptures(board,turn,from).map(({to,taken})=>({from,to,taken})));\n if(captures.length||forced!==null)return captures;\n const moves=[];\n for(const from of starts){\n  const piece=board[from],r=Math.floor(from/8),c=from%8;\n  for(const [dr,dc] of diagonals){\n   if(piece<=2&&dr!==(turn===1?1:-1))continue;\n   let row=r+dr,col=c+dc;\n   while(inside(row,col)&&board[row*8+col]===0){\n    moves.push({from,to:row*8+col});\n    if(piece<=2)break;\n    row+=dr;col+=dc;\n   }\n  }\n }\n return moves;\n}\n\nexport function evaluate(state,computer=2){\n if(state.winner===computer)return 100000;\n if(state.winner===3-computer)return -100000;\n if(state.winner===3)return 0;\n let result=0;\n for(let i=0;i<64;i++){\n  const piece=state.board[i],player=side(piece);\n  if(!player)continue;\n  const row=Math.floor(i/8),col=i%8;\n  const king=piece>=3;\n  const advancement=king?0:(player===1?row:7-row)*4;\n  const center=3.5-Math.max(Math.abs(row-3.5),Math.abs(col-3.5));\n  const value=(king?325:100)+advancement+center*2;\n  result+=(player===computer?1:-1)*value;\n }\n // A very small preference for having material rather than delaying captures.\n result+=(countPieces(state.board,computer)-countPieces(state.board,3-computer))*2;\n return result;\n}\n\nexport function chooseComputerMove(state,level='normal',options={}){\n if(!state||state.winner||state.turn!==2)return null;\n const top=legalMoves(state);\n if(!top.length)return null;\n const depths={normal:1,hard:2,expert:3,master:5};\n const budgets={normal:800,hard:2500,expert:7000,master:17000};\n const depth=depths[level]??1;\n const maxNodes=Math.max(200,Math.min(20000,Number(options.maxNodes)||budgets[level]||800));\n const deadline=Date.now()+Math.max(30,Math.min(800,Number(options.maxMs)||450));\n let visited=0;\n const ordered=(moves,node)=>moves.slice().sort((a,b)=>{\n  const rank=m=>(m.taken!==undefined?100:0)+(node.board[m.from]>=3?7:0);\n  return rank(b)-rank(a)||a.from-b.from||a.to-b.to;\n });\n function search(node,remaining,alpha,beta){\n  visited++;\n  if(!remaining||node.winner||visited>=maxNodes||Date.now()>deadline)return evaluate(node,2);\n  const legal=legalMoves(node);\n  if(!legal.length)return node.turn===2?-100000:100000;\n  const maximize=node.turn===2;\n  let best=maximize?-Infinity:Infinity;\n  for(const move of ordered(legal,node)){\n   const applied=playMove('warcaby',node,node.turn,move);\n   if(applied.error)continue;\n   const score=search(applied.state,remaining-1,alpha,beta);\n   best=maximize?Math.max(best,score):Math.min(best,score);\n   if(maximize)alpha=Math.max(alpha,best);else beta=Math.min(beta,best);\n   if(beta<=alpha||visited>=maxNodes||Date.now()>deadline)break;\n  }\n  return Number.isFinite(best)?best:evaluate(node,2);\n }\n let best=null,bestScore=-Infinity;\n for(const move of ordered(top,state)){\n  const applied=playMove('warcaby',state,2,move);\n  if(applied.error)continue;\n  const score=search(applied.state,depth-1,-Infinity,Infinity);\n  if(score>bestScore){bestScore=score;best=move}\n  if(visited>=maxNodes||Date.now()>deadline)break;\n }\n return best||top[0];\n}\n";
const trainingUI="// Local Warcaby training controller for the existing Gomoku Premium console shell.\n// Training does not touch /auth/match, account sessions or remote chat.\nimport {initialGame,playMove,legalMoves,evaluate,chooseComputerMove} from '/konto/warcaby/bot.mjs';\n\nexport function setupTraining(a){\n const $=a.$;\n let mode='online',generation=0,finished=false,recorded=false;\n let clocks={1:0,2:0},lastTick=0,clockStarted=false,snapshots=[],notes=[];\n const storageKey='gracz-warcaby-training-v1';\n const clone=value=>JSON.parse(JSON.stringify(value));\n const current=()=>a.getCurrent();\n function game(){return current()?.state}\n function announce(t){a.message(t)}\n function format(ms){\n  const seconds=Math.max(0,Math.ceil(ms/1000));\n  return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');\n }\n function displayClocks(){\n  const enabled=Number($('training-time').value)>0&&mode==='training';\n  // White moves first; shared Gomoku clock-1 is black, clock-2 is white.\n  for(const [player,id] of [[1,'clock-2'],[2,'clock-1']]){\n   $(id).hidden=!enabled;\n   if(enabled)$(id).textContent=format(clocks[player]);\n  }\n }\n function readStats(){\n  try{\n   const d=JSON.parse(localStorage.getItem(storageKey)||'{}');\n   return {win:Math.max(0,Number(d.win)||0),draw:Math.max(0,Number(d.draw)||0),loss:Math.max(0,Number(d.loss)||0)};\n  }catch{return {win:0,draw:0,loss:0}}\n }\n function updateStats(){\n  const stats=readStats(),total=stats.win+stats.draw+stats.loss;\n  const rate=total?Math.round(stats.win/total*100):0;\n  $('record-wins').textContent=stats.win;\n  $('record-draws').textContent=stats.draw;\n  $('record-losses').textContent=stats.loss;\n  $('record-total').textContent=total;\n  $('record-rate').textContent=rate+'%';\n  $('records-progress-fill').style.width=rate+'%';\n  $('records-progress').setAttribute('aria-valuenow',String(rate));\n }\n function addResult(result){\n  const stats=readStats();stats[result]++;\n  try{localStorage.setItem(storageKey,JSON.stringify(stats))}catch{}\n  updateStats();\n }\n function hideResult(){$('game-result-modal').hidden=true}\n function showResult(winner){\n  const result=winner===3?'draw':winner===1?'win':'loss';\n  const card=$('game-result-modal').querySelector('.result-card');\n  card.dataset.result=result;\n  $('game-result-title').textContent=result==='win'?'Wygrałeś z komputerem!':result==='loss'?'Przegrałeś z komputerem.':'Partia zakończona remisem.';\n  $('game-result-description').textContent='Warcaby · trening lokalny · '+$('ai-level').selectedOptions[0].textContent.trim();\n  $('game-result-modal').hidden=false;\n  $('game-result-review').focus();\n }\n function finish(){\n  if(finished||!game()?.winner)return;\n  finished=true;generation++;\n  if(!recorded){recorded=true;addResult(game().winner===3?'draw':game().winner===1?'win':'loss')}\n  displayClocks();a.renderBoard();showResult(game().winner);\n }\n function tick(){\n  if(mode!=='training'||finished||!game()||!clockStarted||!Number($('training-time').value))return;\n  const now=performance.now(),delta=Math.max(0,now-lastTick);lastTick=now;\n  clocks[game().turn]=Math.max(0,clocks[game().turn]-delta);\n  if(clocks[game().turn]===0){\n   game().winner=3-game().turn;\n   announce('Koniec czasu: '+(game().winner===1?'wygrywasz.':'wygrywa komputer.'));\n   finish();\n  }\n  displayClocks();\n }\n function renderNotes(){\n  const list=$('chat-messages');list.replaceChildren();\n  if(!notes.length){\n   const p=document.createElement('p');p.className='dock-empty';\n   p.textContent='Notatki treningowe. Nie są zapisywane na serwerze.';list.append(p);\n   $('chat-preview').textContent=p.textContent;\n   return;\n  }\n  for(const note of notes){\n   const p=document.createElement('p'),label=document.createElement('strong');label.textContent='Notatka: ';\n   p.append(label,document.createTextNode(note));list.append(p);\n  }\n  $('chat-preview').textContent=notes[notes.length-1];\n  list.scrollTop=list.scrollHeight;\n }\n function turnFinished(move,actor){\n  if(mode!=='training'||finished||!game())return;\n  const before=game(),response=playMove('warcaby',before,actor,move);\n  if(response.error){announce(response.error);return}\n  // White gets the full thinking time before the first legal move; never start on \"New game\".\n  if(!clockStarted&&actor===1)clockStarted=true;\n  if(before.turn!==response.state.turn&&Number($('training-time').value))\n   clocks[actor]+=Number($('training-increment').value)*1000;\n  const history=[...(before.history||[]),{player:actor,from:move.from,to:move.to}];\n  a.setCurrent({type:'training',state:{...response.state,history},players:['Ty','Komputer'],player:1,playable:true});\n  a.setSelected(response.state.forced!==null&&response.state.turn===1?response.state.forced:null);\n  lastTick=performance.now();\n  a.renderBoard();\n  if(response.state.winner){finish();return}\n  announce(response.state.turn===1?'Twój ruch — wybierz pionek.':'Komputer analizuje ruch…');\n  if(response.state.turn===2)scheduleComputer(generation);\n }\n function scheduleComputer(version){\n  if(mode!=='training'||finished)return;\n  setTimeout(()=>{\n   if(version!==generation||mode!=='training'||finished||!game()||game().turn!==2)return;\n   tick();\n   if(finished)return;\n   let move;\n   try{move=chooseComputerMove(game(),$('ai-level').value)}catch{announce('Nie udało się obliczyć ruchu komputera.');return}\n   if(version!==generation||mode!=='training'||finished)return;\n   if(!move){\n    game().winner=1;finish();return;\n   }\n   turnFinished(move,2);\n  },90);\n }\n async function startTraining(){\n  if(mode!=='training')return;\n  generation++;finished=false;recorded=false;clockStarted=false;snapshots=[];notes=[];\n  hideResult();\n  const minutes=Number($('training-time').value)||0;\n  clocks={1:minutes*60000,2:minutes*60000};\n  const state={...initialGame('warcaby'),history:[]};\n  a.setCurrent({type:'training',state,players:['Ty','Komputer'],player:1,playable:true});\n  a.setSelected(null);lastTick=performance.now();\n  a.renderBoard();displayClocks();renderNotes();updateStats();\n  $('chat-tab').click();\n  announce('Nowa partia z komputerem. Grasz białymi, masz pierwszy ruch.');\n }\n function playTrainingMove(move){\n  if(mode!=='training'||finished||!game()||game().turn!==1)return;\n  if(game().forced==null){\n   snapshots.push({state:clone(game()),clocks:{...clocks},clockStarted});\n   if(snapshots.length>20)snapshots.shift();\n  }\n  tick();\n  if(!finished)turnFinished(move,1);\n }\n function undoTraining(){\n  if(mode!=='training'||finished||!snapshots.length){\n   announce('Nie ma jeszcze tury do cofnięcia.');return;\n  }\n  generation++;\n  const last=snapshots.pop();\n  clocks={...last.clocks};clockStarted=last.clockStarted;\n  a.setCurrent({type:'training',state:last.state,players:['Ty','Komputer'],player:1,playable:true});\n  a.setSelected(null);lastTick=performance.now();\n  a.renderBoard();displayClocks();\n  announce('Cofnięto całą turę — Twój ruch i odpowiedź komputera.');\n }\n function hint(){\n  if(mode!=='training'||finished||game()?.turn!==1){announce('Podpowiedź jest dostępna podczas Twojej tury.');return}\n  const moves=legalMoves(game());\n  if(!moves.length){announce('Brak dostępnych ruchów.');return}\n  let best=moves[0],score=-Infinity;\n  for(const move of moves){\n   const r=playMove('warcaby',game(),1,move);\n   if(r.error)continue;\n   const value=evaluate(r.state,1)+(move.taken!==undefined?10:0);\n   if(value>score){score=value;best=move}\n  }\n  a.setSelected(best.from);a.renderBoard();\n  announce('Podpowiedź: '+a.squareLabel(best.from)+' → '+a.squareLabel(best.to)+'.');\n }\n function setMode(next){\n  mode=next;generation++;finished=false;\n  a.setMode(next);\n  $('training-mode').classList.toggle('active',next==='training');\n  $('online-mode').classList.toggle('active',next==='online');\n  $('training-mode').setAttribute('aria-pressed',String(next==='training'));\n  $('online-mode').setAttribute('aria-pressed',String(next==='online'));\n  $('training-settings').hidden=next!=='training';\n  $('training-records').hidden=next!=='training';\n  $('online-settings').hidden=next!=='online';\n  $('chat-status').textContent=next==='training'?'Notatki treningowe · tylko w tej przeglądarce, bez zapisu na serwerze':'Czat partii online';\n  $('checkers-refresh').title=next==='training'?'Cofnij turę':'Odśwież partię';\n  $('checkers-refresh').setAttribute('aria-label',$('checkers-refresh').title);\n  $('checkers-refresh').dataset.tooltip=$('checkers-refresh').title;\n  $('chat-input').disabled=next==='online'&&!a.validMatch;\n  $('chat-send').disabled=next==='online'&&!a.validMatch;\n  hideResult();a.setCurrent(null);a.setSelected(null);\n  if(next==='training')void startTraining();\n  else {\n   displayClocks();a.renderPreview();void a.loadRooms();\n   if(a.validMatch)void a.refresh(true).then(()=>a.refreshChat());\n   else announce('Zaproś znajomego lub wybierz przyjętą partię.');\n  }\n }\n const hints={\n  normal:'Normalny — podstawowa analiza ruchów, obowiązkowych bić i pionków.',\n  hard:'Trudny — sprawdza odpowiedzi przeciwnika i taktykę kolejnych ruchów.',\n  expert:'Ekspert — analizuje więcej wariantów, bić i odpowiedzi.',\n  master:'Arcymistrz — najgłębsze dostępne przeszukiwanie lokalnego silnika Warcabów.'\n };\n function updateHint(){$('ai-hint').textContent=hints[$('ai-level').value]||hints.normal}\n $('training-mode').addEventListener('click',()=>setMode('training'));\n $('online-mode').addEventListener('click',()=>setMode('online'));\n $('restart').addEventListener('click',()=>void startTraining());\n $('training-undo').addEventListener('click',undoTraining);\n $('training-hint').addEventListener('click',hint);\n for(const id of ['training-time','training-increment'])\n  $(id).addEventListener('change',()=>{if(mode==='training')void startTraining()});\n $('ai-level').addEventListener('change',updateHint);\n $('game-result-close').addEventListener('click',hideResult);\n $('game-result-review').addEventListener('click',hideResult);\n $('game-result-new').addEventListener('click',()=>void startTraining());\n setInterval(tick,250);\n updateHint();updateStats();\n return {startTraining,playTrainingMove,undoTraining,renderNotes,setMode,getMode:()=>mode};\n}\n";
const secure={"Content-Security-Policy":"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY"};
const html=getSharedGameConsoleHtml().replaceAll('Gomoku','Warcaby').replaceAll('GOMOKU','WARCABY').replace('<body>','<body class="warcaby-console">').replace('href="/konto/gomoku/styl.css"','href="/konto/gomoku/styl.css"><link rel="stylesheet" href="/konto/warcaby/styl.css"').replace('src="/konto/gomoku/app.js"','src="/konto/warcaby/app.js"').replace('id="refresh-match" title="Odśwież partię"','id="refresh-match" title="Odśwież partię"').replace('data-tooltip="Odśwież partię" hidden','data-tooltip="Odśwież partię"').replace('Plansza Warcaby 15 na 15','Plansza Warcabów 8 na 8').replace('Plansza 15 × 15','Plansza 8 × 8').replace('class="board" id="board"','class="board checkers-grid" id="board"').replace('id="board" role="grid" aria-label="Plansza Warcabów 8 na 8"></div></div>','id="board" role="grid" aria-label="Plansza Warcabów 8 na 8"></div></div>').replace('Czarne — zaczynają','Czarne — drugie')
.replace('<strong id="black-name">Ty</strong>','<strong id="black-name">Komputer</strong>')
.replace('<strong id="white-name">Komputer</strong>','<strong id="white-name">Ty</strong>')
