const js="'use strict';\n(()=>{const $=id=>document.getElementById(id),matchId=new URLSearchParams(location.search).get('match')||'';\nconst validMatch=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(matchId);\nlet current=null,selected=null,busy=false,loading=false,chatBusy=false,chatSignature='',rotated=false;\nlet mode=validMatch?'online':'training',trainingController=null;\nconst board=$('board'),status=$('game-state');\nconst squareLabel=i=>'ABCDEFGH'[i%8]+(8-Math.floor(i/8));\nfunction message(t){status.textContent=t}\nasync function api(path,options){const response=await fetch('/auth/'+path,{credentials:'same-origin',cache:'no-store',...options});let data;try{data=await response.json()}catch{throw Error('Brak odpowiedzi serwera')}if(!response.ok||!data.ok)throw Error(data.error||'Błąd połączenia');return data}\n\n/* One capture is a hop. The rules engine, not this visual guide, decides legality. */\nfunction captureOptions(board,from,player){\n const piece=board[from],r=Math.floor(from/8),c=from%8,result=[];\n if(!piece||(piece===1||piece===3?1:2)!==player)return result;\n for(const dr of [-1,1])for(const dc of [-1,1]){\n  if(piece<=2&&dr!==(player===1?1:-1))continue;\n  if(piece<=2){\n   const mr=r+dr,mc=c+dc,tr=r+2*dr,tc=c+2*dc;\n   if(mr<0||mr>7||mc<0||mc>7||tr<0||tr>7||tc<0||tc>7)continue;\n   const taken=mr*8+mc,to=tr*8+tc,target=board[taken];\n   if(target&&(target===1||target===3?1:2)!==player&&!board[to])result.push({to,taken});\n  }else{\n   let rr=r+dr,cc=c+dc,taken=null;\n   while(rr>=0&&rr<8&&cc>=0&&cc<8){\n    const at=rr*8+cc,p=board[at];\n    if(!p){if(taken!==null)result.push({to:at,taken})}\n    else if(taken===null&&(p===1||p===3?1:2)!==player)taken=at;\n    else break;\n    rr+=dr;cc+=dc;\n   }\n  }\n }\n return result;\n}\nfunction captureTargets(board,from,player){return captureOptions(board,from,player).map(move=>move.to)}\n/* Min/max describes branching routes; never claim the longest route is required\n   when the published rules allow a shorter valid alternative. */\nfunction captureRange(board,from,player,depth=0){\n if(depth>=12)return {min:0,max:0};\n const moves=captureOptions(board,from,player);\n if(!moves.length)return {min:0,max:0};\n let min=Infinity,max=0;\n for(const move of moves){\n  const next=board.slice(),piece=next[from];\n  next[from]=0;next[move.taken]=0;next[move.to]=piece;\n  if(piece===1&&Math.floor(move.to/8)===7)next[move.to]=3;\n  if(piece===2&&Math.floor(move.to/8)===0)next[move.to]=4;\n  const future=captureRange(next,move.to,player,depth+1);\n  min=Math.min(min,1+future.min);max=Math.max(max,1+future.max);\n }\n return {min,max};\n}\nfunction captureSources(state,player){\n if(state.forced!=null)return [state.forced];\n return state.board.map((piece,i)=>((piece===player||piece===player+2)&&captureTargets(state.board,i,player).length)?i:-1).filter(i=>i>=0);\n}\nlet captureNoticeKey='';\nfunction captureCount(n){return n+' '+(n===1?'bicie':(n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'bicia':'bić'))}\nfunction syncCaptureNotice(reopen=false){\n const notice=$('checkers-capture-notice'),s=current?.state,active=s&&!s.winner&&current.playable&&s.turn===current.player;\n if(!active){notice.hidden=true;captureNoticeKey='';return}\n const sources=captureSources(s,current.player),forced=s.forced??null;\n let from=forced!==null?forced:selected;\n if(from===null||!sources.includes(from)){\n  from=sources.reduce((best,i)=>captureRange(s.board,i,current.player).max>captureRange(s.board,best,current.player).max?i:best,sources[0]??-1);\n }\n if(from<0){notice.hidden=true;captureNoticeKey='';return}\n const range=captureRange(s.board,from,current.player);\n if(!range.max||(!reopen&&forced===null&&range.max<2)){notice.hidden=true;captureNoticeKey='';return}\n const key=[mode,s.moves,s.turn,forced,from,range.min,range.max].join(':');\n if(reopen||key!==captureNoticeKey){\n  $('checkers-capture-title').textContent=forced!==null?'Kontynuuj obowiązkowe bicie!':reopen?'Bicie obowiązkowe!':'Wielokrotne bicie!';\n  $('checkers-capture-text').textContent=range.min===range.max\n   ?(forced!==null?'Pozostało '+captureCount(range.max)+'. Pionek oznaczony na czerwono musi bić dalej.':'Masz '+captureCount(range.max)+' pionków. Wykonaj wszystkie kolejne bicia.')\n   :('Możliwe '+captureCount(range.min)+' – '+captureCount(range.max)+'. Po każdym biciu sprawdź kolejną kropkę.');\n  notice.hidden=false;captureNoticeKey=key;\n }\n}\n$('checkers-capture-dismiss').addEventListener('click',()=>{$('checkers-capture-notice').hidden=true});\nfunction destinations(from){\n if(!current)return [];\n const s=current.state,b=s.board,p=b[from],player=current.player,forced=s.forced??null;\n if(!p||!(p===player||p===player+2)||s.winner||(forced!==null&&forced!==from))return [];\n const captures=captureTargets(b,from,player);\n if(forced!==null||b.some((piece,i)=>(piece===player||piece===player+2)&&captureTargets(b,i,player).length))return captures;\n const r=Math.floor(from/8),c=from%8,result=[];\n for(const dr of [-1,1])for(const dc of [-1,1]){\n  if(p<=2&&dr!==(player===1?1:-1))continue;\n  let rr=r+dr,cc=c+dc;\n  while(rr>=0&&rr<8&&cc>=0&&cc<8&&!b[rr*8+cc]){\n   result.push(rr*8+cc);\n   if(p<=2)break;\n   rr+=dr;cc+=dc;\n  }\n }\n return result;\n}\nfunction crownEmblem(){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),use=document.createElementNS(ns,'use');svg.setAttribute('class','crown');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');use.setAttribute('href','#checkers-crown');svg.append(use);return svg}\nfunction renderBoard(){if(!current)return;board.classList.remove('preview');const s=current.state,fragment=document.createDocumentFragment();\n const active=!s.winner&&current.playable&&s.turn===current.player;\n if(active&&s.forced!=null)selected=s.forced;\n const sources=active?captureSources(s,current.player):[];\n const targets=selected===null?(active?sources.flatMap(from=>captureTargets(s.board,from,current.player)):[]):destinations(selected);\n const captures=selected!==null&&active?captureTargets(s.board,selected,current.player):[];\n const possible=[...new Set(targets)];\n const order=Array.from({length:64},(_,i)=>rotated?63-i:i);\n for(const i of order){const b=document.createElement('button');b.type='button';b.className='square '+((Math.floor(i/8)+i%8)%2?'dark':'light');\n if(i===selected)b.classList.add('selected');\n if(possible.includes(i))b.classList.add('possible');\n if(captures.includes(i)||(selected===null&&sources.some(from=>captureTargets(s.board,from,current.player).includes(i))))b.classList.add('capture-target');\n if(active&&s.forced===i)b.classList.add('must-continue');\n if(active&&sources.includes(i))b.classList.add('capture-source');\n const p=s.board[i];b.setAttribute('role','gridcell');b.setAttribute('aria-label',squareLabel(i)+(p?' pionek '+((p%2)?'biały':'czarny'):'')+(b.classList.contains('capture-target')?' — pole obowiązkowego bicia':'')+(b.classList.contains('must-continue')?' — kontynuuj bicie':''));\n\n if(p){const token=document.createElement('span');token.className='piece '+((p===1||p===3)?'white':'black')+(p>=3?' king':'')+(b.classList.contains('must-continue')?' must-continue':'');if(p>=3)token.append(crownEmblem());b.append(token)}\n b.addEventListener('click',()=>choose(i));fragment.append(b)}board.replaceChildren(fragment);\n $('session-heading').textContent=s.winner?(s.winner===3?'Remis':'Wygrywa '+current.players[s.winner-1]):s.forced!=null?'Kontynuuj bicie':'Ruch: '+current.players[s.turn-1];\n $('move-count').textContent='Ruch '+s.moves;\n $('white-name').textContent=current.players[0];$('black-name').textContent=current.players[1];\n  $('dock-status').textContent=mode==='training'?'TRENING':'ONLINE';$('room-tag').textContent=mode==='training'?'Z KOMPUTEREM':'ONLINE';$('board-help').textContent=mode==='training'?'Bicie jest obowiązkowe · grasz białymi pionkami.':'Bicie jest obowiązkowe. Ruchy i wyniki zatwierdza serwer.';\n if(mode==='training'){\n  $('turn-label').textContent=s.winner?(s.winner===3?'Remis':s.winner===1?'Wygrana':'Przegrana'):s.turn===1?'Twój ruch':'Ruch komputera';\n }\n renderHistory();syncCaptureNotice()}\nfunction renderHistory(){const list=$('moves-list');list.replaceChildren();const hist=current?.state?.history||[];\n for(const m of hist){const li=document.createElement('li');li.textContent=current.players[m.player-1]+': '+squareLabel(m.from)+' → '+squareLabel(m.to);list.append(li)}\n if(!hist.length){const li=document.createElement('li');li.textContent='Historia pojawi się po pierwszym ruchu';list.append(li)}}\nasync function refresh(force=false){if(mode!=='online'||!validMatch||loading||busy||document.hidden&&!force)return;loading=true;\n try{const d=await api('match?id='+encodeURIComponent(matchId));if(d.match.game!=='warcaby'){message('Ten pokój nie jest partią Warcabów.');return}\n if(!current||d.match.version!==current.version||force){current=d.match;if(current.state.forced!=null&&current.state.turn===current.player)selected=current.state.forced;else selected=null;renderBoard()}\n message(current.playable?'Partia zabezpieczona.':'Rozgrywka zablokowana.');}\n catch(e){$('dock-status').textContent='Offline';message('Synchronizacja: '+e.message)}\n finally{loading=false}}\nasync function choose(i){if(!current||busy||!current.playable||current.state.winner||current.state.turn!==current.player)return;\n const state=current.state,p=state.board[i],forced=state.forced??null;\n const sources=captureSources(state,current.player),mandatory=sources.length>0;\n if(p&&(p===current.player||p===current.player+2)){\n  if(forced!==null&&i!==forced){syncCaptureNotice(true);return}\n  if(mandatory&&!sources.includes(i)){selected=forced;renderBoard();syncCaptureNotice(true);return}\n  selected=i;renderBoard();return;\n }\n if(selected===null||!destinations(selected).includes(i)){\n  if(mandatory)syncCaptureNotice(true);\n  return;\n }\n if(mode==='training'){playTrainingMove({from:selected,to:i});return}\n busy=true;try{const d=await api('match',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:matchId,version:current.version,move:{from:selected,to:i}})});\n current=d.match;selected=current.state.forced!=null&&current.state.turn===current.player?current.state.forced:null;renderBoard();message('Ruch zatwierdzony przez serwer')}\n catch(e){message(e.message);await refresh(true)}finally{busy=false}}\nasync function refreshChat(){if(mode!=='online'||!current||!current.playable||document.hidden)return;try{const d=await api('match/chat?id='+encodeURIComponent(matchId));\n const signature=d.messages.map(x=>x.id).join('|');if(signature===chatSignature)return;chatSignature=signature;\n const fragment=document.createDocumentFragment();for(const m of d.messages){const p=document.createElement('p'),name=document.createElement('strong');name.textContent=(current.players[m.player-1]||'Gracz')+': ';p.append(name,document.createTextNode(m.body));fragment.append(p)}\n $('chat-messages').replaceChildren(fragment);$('chat-preview').textContent=$('chat-messages').textContent;$('chat-messages').scrollTop=$('chat-messages').scrollHeight}catch(e){message('Czat: '+e.message)}}\n$('chat-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('chat-input'),value=input.value.trim();if(!value)return;\n if(mode==='training'){trainingNotes.push(value);input.value='';renderTrainingNotes();return}\n if(chatBusy||!current||!current.playable)return;\n chatBusy=true;try{await api('match/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:matchId,message:value})});input.value='';await refreshChat()}catch(error){message(error.message)}finally{chatBusy=false}});\nfor(const b of [$('chat-tab'),$('history-tab')])b.addEventListener('click',()=>{const chat=b.id==='chat-tab';$('chat-panel').hidden=!chat;$('moves-panel').hidden=chat;for(const x of [$('chat-tab'),$('history-tab')]){x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))}});\n$('refresh-match').addEventListener('click',()=>{refresh(true);refreshChat()});\n$('rotate-board').addEventListener('click',()=>{rotated=!rotated;renderBoard()});\n$('checkers-history').addEventListener('click',()=>{$('history-tab').click()});\n$('checkers-settings').addEventListener('click',()=>{$('console-config-open').click()});\n$('checkers-chat').addEventListener('click',()=>{$('chat-tab').click();if(!$('chat-input').disabled)$('chat-input').focus()});\n$('checkers-refresh').addEventListener('click',()=>{if(mode==='training'){undoTraining();return}void loadRooms();void refresh(true);void refreshChat()});\n$('fullscreen-game').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.layout').requestFullscreen()}catch{message('Tryb pełnoekranowy niedostępny')}});\n\n\nfunction renderPreview(){\n $('checkers-capture-notice').hidden=true;captureNoticeKey='';\n const fragment=document.createDocumentFragment();\n for(let i=0;i<64;i++){\n  const r=Math.floor(i/8),c=i%8,dark=(r+c)%2===1,p=dark?(r<3?1:r>4?2:0):0;\n  const b=document.createElement('button');b.type='button';b.disabled=true;b.className='square '+(dark?'dark':'light');\n  b.setAttribute('role','gridcell');b.setAttribute('aria-label',squareLabel(i)+(p?(p===1?' biały pionek':' czarny pionek'):' puste pole'));\n  if(p){const token=document.createElement('span');token.className='piece '+(p===1?'white':'black');b.append(token)}\n  fragment.append(b);\n }\n board.replaceChildren(fragment);board.classList.add('preview');\n $('session-heading').textContent='Plansza Warcabów 8 × 8';$('white-name').textContent='Białe';$('black-name').textContent='Czarne';\n $('room-tag').textContent='PODGLĄD';$('dock-status').textContent='BRAK PARTII';\n $('board-help').textContent='12 białych i 12 czarnych pionków · wybierz przeciwnika';\n $('turn-label').textContent='Oczekiwanie';$('game-state').textContent='Zaproś znajomego lub otwórz przyjęte wyzwanie.';\n \n}\nasync function loadRooms(){\n const select=$('room-select');select.replaceChildren();\n const empty=document.createElement('option');empty.value='';empty.textContent='Wybierz przyjętą partię';select.append(empty);\n try{\n  const data=await api('social/challenges');\n  const active=(data.challenges||[]).filter(x=>x.game==='warcaby'&&x.status==='accepted');\n  for(const item of active){const opt=document.createElement('option');opt.value=item.id;opt.textContent='Warcaby · '+item.opponent;select.append(opt)}\n  $('account-note').textContent=active.length?'Wybierz pokój i graj online.':'Zaproś znajomego do Warcabów i poczekaj na akceptację.';\n }catch(e){$('account-note').textContent='Zaloguj się, aby zobaczyć swoje pokoje.'}\n}\n$('create-room').addEventListener('click',async()=>{\n const input=$('create-room-friend'),name=input.value.trim(),button=$('create-room');\n if(!name){$('create-room-status').textContent='Podaj nick znajomego.';return}\n button.disabled=true;\n try{\n  await api('social/challenges',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'send',nickname:name,game:'warcaby'})});\n  $('create-room-status').textContent='Zaproszenie wysłane. Gra ruszy po zaakceptowaniu przez znajomego.';await loadRooms();\n }catch(e){$('create-room-status').textContent=e.message}\n finally{button.disabled=false}\n});\n$('reload-rooms').addEventListener('click',loadRooms);\n$('join-room').addEventListener('click',()=>{const id=$('room-select').value;if(id)location.href='/konto/warcaby/?match='+encodeURIComponent(id);else $('account-note').textContent='Najpierw wybierz zaakceptowaną partię.'});\n$('invite-friend').addEventListener('click',()=>{document.querySelector('.sidebar').scrollTop=0;$('create-room-friend').focus()});\n$('focus-start').addEventListener('click',()=>{if(mode==='training')void startTraining();else $('create-room-friend').focus()});\n$('howto-open').addEventListener('click',()=>{location.href='https://gracz.pl/gry/warcaby/zasady/'});\n\n$('focus-game').addEventListener('click',async()=>{try{await document.querySelector('.boardframe').requestFullscreen()}catch(e){message('Nie udało się powiększyć planszy')}});\nconst modal=$('console-config-modal');\nfunction layout(left,right){document.querySelector('.sidebar').hidden=!left;document.querySelector('.side-dock').hidden=!right;document.querySelector('.layout').classList.toggle('no-sidebar',!left);document.querySelector('.boardarea').classList.toggle('no-dock',!right)}\nconst consoleParts=[\n ['.sidebar','Lewy panel','Nawigacja i pokoje','▣'],\n ['.side-dock','Prawy panel','Czat i ruchy','▤'],\n ['.players','Zawodnicy','Informacje o graczach','♟'],\n ['.premium-quick-links','Miniatury','Szybkie skróty','✦']\n];\nfunction showConfigTiles(){\n const list=$('console-config-tiles');list.replaceChildren();let visible=0;\n for(const [selector,name,detail,symbol] of consoleParts){\n  const target=document.querySelector(selector),shown=!target.hidden;if(shown)visible++;\n  const tile=document.createElement('div');tile.className='console-config-tile'+(shown?'':' is-hidden');\n  const icon=document.createElement('span');icon.className='console-tile-icon';icon.textContent=symbol;\n  const info=document.createElement('div');info.className='console-tile-info';\n  const heading=document.createElement('strong');heading.textContent=name;\n  const subtitle=document.createElement('small');subtitle.textContent=detail;info.append(heading,subtitle);\n  const button=document.createElement('button');button.type='button';button.className='console-tile-action';button.textContent=shown?'Ukryj':'Dodaj';\n  button.addEventListener('click',()=>{\n   if(selector==='.sidebar'||selector==='.side-dock'){const l=!document.querySelector('.sidebar').hidden,r=!document.querySelector('.side-dock').hidden;layout(selector==='.sidebar'?!l:l,selector==='.side-dock'?!r:r)}\n   else target.hidden=!shown;\n   showConfigTiles();\n  });\n  tile.append(icon,info,button);list.append(tile);\n }\n $('console-config-count').textContent='Widoczne: '+visible+' z '+consoleParts.length;\n}\n\n$('console-config-open').addEventListener('click',()=>{modal.hidden=false;showConfigTiles();$('console-config-close').focus()});\n$('console-config-close').addEventListener('click',()=>modal.hidden=true);\n$('console-config-done').addEventListener('click',()=>modal.hidden=true);\n$('console-config-reset').addEventListener('click',()=>{layout(true,true);document.querySelector('.players').hidden=false;document.querySelector('.premium-quick-links').hidden=false;showConfigTiles()});\n$('console-preset-full').addEventListener('click',()=>layout(true,true));\n$('console-preset-social').addEventListener('click',()=>layout(false,true));\n$('console-preset-board').addEventListener('click',()=>{layout(false,false);modal.hidden=true});\n$('focus-exit').addEventListener('click',()=>layout(true,true));\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)modal.hidden=true});\n\nfunction playTrainingMove(move){trainingController?.playTrainingMove(move)}\nfunction undoTraining(){trainingController?.undoTraining()}\nfunction renderTrainingNotes(){trainingController?.renderNotes()}\nfunction startTraining(){return trainingController?.startTraining()}\nfunction initializeWarcaby(){\n import('/konto/warcaby/training-ui.mjs').then(mod=>{\n  trainingController=mod.setupTraining({\n   $,validMatch,squareLabel,message,\n   getCurrent:()=>current,setCurrent:value=>{current=value},\n   setSelected:value=>{selected=value},\n   setMode:value=>{mode=value},\n   renderBoard,renderPreview,loadRooms,refresh,refreshChat\n  });\n  trainingController.setMode(validMatch?'online':'training');\n }).catch(error=>{\n  message('Trening nie jest dostępny: '+error.message);\n  mode='online';$('training-settings').hidden=true;$('training-records').hidden=true;\n  $('online-settings').hidden=false;renderPreview();void loadRooms();\n  if(validMatch)void refresh(true).then(refreshChat);\n });\n}\n\n// Training and online games share the visual shell, but never share state or moves.\ninitializeWarcaby();\nsetInterval(()=>{if(mode==='online'){refresh();refreshChat()}},4000);\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden&&mode==='online'){refresh(true);refreshChat()}})})();";
export function serveCheckersConsole(req,res,url){if(req.method!=='GET')return false;const path=url.pathname.replace(/\/+$/,'')||'/';const output={'/konto/warcaby':['text/html; charset=utf-8',html],'/konto/warcaby/styl.css':['text/css; charset=utf-8',css],'/konto/warcaby/app.js':['application/javascript; charset=utf-8',js],'/konto/warcaby/rules.mjs':['application/javascript; charset=utf-8',trainingRules],'/konto/warcaby/bot.mjs':['application/javascript; charset=utf-8',trainingBot],'/konto/warcaby/training-ui.mjs':['application/javascript; charset=utf-8',trainingUI]}[path];if(!output)return false;res.writeHead(200,{...secure,'Content-Type':output[0],'Content-Length':Buffer.byteLength(output[1])});res.end(output[1]);return true;}
